spec.setup_code:
var A = new api.THREE.Vector3(2, 0, 0);
var origin = new api.THREE.Vector3(0, 0, 0);
var arrowA = new api.THREE.ArrowHelper(A.clone().normalize(), origin, A.length(), 0x4C72B0);
var arrowB = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 1.5, 0xE8593C);
var arrowR = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 1, 0x2E7D32);
api.group.add(arrowA);
api.group.add(arrowB);
api.group.add(arrowR);
return {
  update: function(t) {
    var angle = t * 0.005;
    var B = new api.THREE.Vector3(1.5 * Math.cos(angle), 1.5 * Math.sin(angle), 0);
    arrowB.setDirection(B.clone().normalize());
    arrowB.setLength(Math.max(B.length(), 0.01));
    var R = A.clone().add(B);
    var mag = R.length();
    if (mag > 0.001) {
      arrowR.setDirection(R.clone().normalize());
      arrowR.setLength(mag);
    }
  }
};

return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    function arrow(x0, y0, x1, y1, color) {
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
      var ang = Math.atan2(y1 - y0, x1 - x0);
      var hs = 10;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x1 - hs * Math.cos(ang - Math.PI / 6), y1 - hs * Math.sin(ang - Math.PI / 6));
      ctx.lineTo(x1 - hs * Math.cos(ang + Math.PI / 6), y1 - hs * Math.sin(ang + Math.PI / 6));
      ctx.closePath();
      ctx.fill();
    }
    var scale = Math.min(W, H) * 0.012;
    var ox = W * 0.3, oy = H * 0.75;
    var Ax = 5 * scale, Ay = 0;
    var angle = Math.PI / 4 + Math.sin(t * 0.01) * 0.25;
    var Bx = 4 * scale * Math.cos(angle), By = -4 * scale * Math.sin(angle);
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = '#999999';
    ctx.beginPath();
    ctx.moveTo(ox + Ax, oy + Ay);
    ctx.lineTo(ox + Ax + Bx, oy + Ay + By);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ox + Bx, oy + By);
    ctx.lineTo(ox + Ax + Bx, oy + Ay + By);
    ctx.stroke();
    ctx.setLineDash([]);
    arrow(ox, oy, ox + Ax, oy + Ay, '#4C72B0');
    arrow(ox, oy, ox + Bx, oy + By, '#E8593C');
    arrow(ox, oy, ox + Ax + Bx, oy + Ay + By, '#2E7D32');
    ctx.fillStyle = '#333';
    ctx.font = '14px sans-serif';
    ctx.fillText('A', ox + Ax / 2 - 10, oy + Ay - 8);
    ctx.fillText('B', ox + Bx / 2, oy + By - 8);
    ctx.fillText('R = A + B (diagonal)', ox + (Ax + Bx) / 2, oy + (Ay + By) / 2 - 12);
  }
};
